examples.template:
LazyColumn(modifier = Modifier.semantics { contentDescription = {{label}} }) {
    item {
        MonarchInboxRow(
            title = {{rows.0.title}},
            onClick = {},
            current = {{rows.0.id}} == {{current}},
            preview = {{rows.0.preview}},
            timestamp = {{rows.0.timestamp|millis}},
            now = {{now|millis}},
            avatarName = {{rows.0.title}},
            icon = { MonarchIcon(SampleIcons.Inbox, contentDescription = null) },
            iconLabel = {{iconLabel}},
            badges = { MonarchBadge(text = {{rows.0.status}}, tone = {{rows.0.tone|tone}}) },
            trailing = {
                Row(
                    horizontalArrangement = Arrangement.spacedBy(MonarchTheme.spacing.space2),
                    verticalAlignment = Alignment.CenterVertically,
                ) {
                    MonarchText(text = "#" + {{rows.0.id}}, style = MonarchTextStyle.Caption)
                    MonarchAvatar(image = null, name = {{assignee}}, size = MonarchAvatarSize.Xs)
